export const lessons = rows.map((r,i) => {
  const module = Math.floor(i/3)+1;
  const track = modules[module-1][2];
  const html = r[3] || '<p id="out">Ready</p>';
  const css = r[4] && r[4].includes('{') ? r[4] : '';
  const js = r[5] && (r[5].includes('const ') || r[5].includes('document.') || r[5].includes('async ') || r[5].includes('Promise.')) ? r[5] : '';
  const practice = js ? r[6] : css ? r[5] : r[4];
  const qOffset = js ? 7 : css ? 6 : 5;
  return {
    id:`lesson-${String(i+1).padStart(2,'0')}`,order:i+1,module,track,title:r[0],minutes:18+(i%3)*4,
    prerequisites:i ? [`lesson-${String(i).padStart(2,'0')}`] : [],objective:r[1],explanation:r[2],
    example:{html,css,js},guided:practice,challenge:challengePrompts[i],
    starter:{html:html.replace(/>[^<>]+</g,'> </'),css:css?'/* Add your CSS here */':'',js:js?'// Add your JavaScript here':''},
    hints:[`Think about the lesson goal: ${r[1]}`,`Compare your work with the example, especially the ${track==='css'?'selector and declaration':track==='js'?'value and visible output':'elements and attributes'}.`,`Start from this pattern: ${track==='css'?css.slice(0,80):track==='js'?js.slice(0,80):html.slice(0,80)}`],
    solution:{html,css,js,explanation:`This example demonstrates ${r[0].toLowerCase()}. ${r[2]}`},
    quiz:[{question:r[qOffset],choices:[r[qOffset+1],r[qOffset+2],r[qOffset+3]],answer:0,explanation:r[2]},{question:`What is the main goal of this lesson?`,choices:[r[1],`Memorize one exact page design`,`Skip testing the result`],answer:0,explanation:r[1]}],
    recap:r[1], commonMistake:`A common mistake is to copy the example without checking how it works. Change one part and run it again.`
  };
});
lessons.forEach((lesson,i)=>{const [question,...choices]=secondQuestions[i];lesson.quiz[1]={question,choices,answer:0,explanation:lesson.explanation}});

// The fully worked first coding lesson uses two distinct drafts and structure-based checks.
Object.assign(lessons[5],{
  minutes:25,
  explanation:'A heading names a section and helps readers scan the page. Use one h1 for the main page title, then h2 for a section inside it. Paragraphs contain the ideas beneath each heading. The browser gives headings a default size, but their meaning matters more than their appearance.',
  example:{html:'<h1>My learning page</h1>\n<p>I am learning how to build websites.</p>\n<h2>My interests</h2>\n<p>I enjoy drawing and coding.</p>',css:'',js:''},
  starter:{html:'<!-- Write your introduction here -->\n',css:'',js:''},
  challengeStarter:{html:'<!-- Create an About My Website section -->\n',css:'',js:''},
  guided:'Add one main heading, an introduction paragraph, a second-level interests heading, and a paragraph about those interests.',
  challenge:'Create an “About My Website” section with an appropriate heading and two nonempty paragraphs. Use your own wording.',
  guidedRequirements:['One nonempty h1','An introduction paragraph','One nonempty h2 after the h1','A second nonempty paragraph about interests'],
  challengeRequirements:['An About My Website section heading','Two nonempty paragraphs in that section'],
  hints:['Use h1 for the page title and h2 for the interests section.','Write each heading between matching opening and closing tags, then add a p after each heading.','For example: <h1>My page</h1> <p>Welcome...</p> <h2>Interests</h2> <p>I like...</p>'],
  solution:{html:'<h1>My learning page</h1>\n<p>Welcome! I am practicing how to write web pages.</p>\n<h2>My interests</h2>\n<p>I like drawing, music, and learning new skills.</p>',css:'',js:'',explanation:'The h1 gives the page a main title. The first p introduces the page. The h2 starts a smaller section, and the final p gives that section its content. Your words may be different.'},
  challengeSolution:{html:'<section>\n  <h2>About My Website</h2>\n  <p>This website shares what I am learning.</p>\n  <p>I will add projects as I practice.</p>\n</section>',css:'',js:'',explanation:'A section groups this topic, its h2 names it, and both paragraphs contain their own ideas. Other meaningful wording is valid.'},
  quiz:[{question:'Which heading is the main page title?',choices:['h1','h2','p'],answer:0,explanation:'h1 identifies the main heading for the page.'},{question:'What should you use for a paragraph of related sentences?',choices:['p','h1','strong'],answer:0,explanation:'The p element contains a paragraph.'},{question:'What heading follows an h1 for a section?',choices:['h2','h4','p'],answer:0,explanation:'h2 is the next heading level for a section.'}],
  commonMistake:'Skipping from h1 straight to h4 for visual size changes the document outline. Use heading levels for meaning; use CSS for appearance.'
});

export const projects = [
 {id:'project-1',title:'Personal Introduction Page',after:12,track:'html',minutes:120,brief:'Build a useful introduction page using the HTML skills from Modules 1–4. Fictional details are welcome. The practice contact form does not send messages.',skills:['Structure','Links','Images','Tables','Forms'],requirements:['Page title and introductory heading','About section','Interests or learning-goals list','Image with suitable alt text','Section navigation','Study-schedule table','Labeled practice contact form','Footer'],extensions:['FAQ with details and summary','Second local page'],starter:{html:'<!doctype html>\n<html lang="en"><head><title>About me</title></head><body>\n<h1>About me</h1>\n</body></html>',css:'',js:''},solution:{html:'<!doctype html><html lang="en"><head><title>About me</title></head><body><header><h1>About me</h1><nav><a href="#about">About</a> <a href="#schedule">Schedule</a></nav></header><main><section id="about"><h2>About</h2><p>I am learning web development.</p><ul><li>Build a website</li></ul><img src="data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%20160%20100%22%3E%3Crect%20width=%22160%22%20height=%22100%22%20fill=%22%23dce8fa%22/%3E%3C/svg%3E" alt="Illustrated portrait placeholder"></section><section id="schedule"><h2>Study schedule</h2><table><caption>Weekly plan</caption><tr><th>Day</th><th>Topic</th></tr><tr><td>Monday</td><td>HTML</td></tr></table></section><section><h2>Practice contact form</h2><p>This form does not send messages.</p><form><label for="email">Email</label><input id="email" type="email"><button>Practice submit</button></form></section></main><footer>Made while learning HTML</footer></body></html>',css:'',js:'',explanation:'Semantic sections organize the page. The navigation points to real ids, the table presents a schedule, and the form is clearly identified as practice.'}},
 {id:'project-2',title:'Responsive Landing Page',after:24,track:'css',minutes:180,brief:'Style a copy of your introduction project as a landing page for a fictional product, club, service, or learning community. Make every action meaningful.',skills:['Typography','Flexbox','Grid','Responsive CSS','Focus'],requirements:['Header and working navigation','Hero with meaningful primary action','Benefits and card section','Final call to action and footer','Consistent colors and type','Reusable classes','Flexible layout on narrow screens','Responsive images if used','Visible focus and readable contrast','Subtle transition with reduced-motion support'],extensions:['Second theme','Print styling'],starter:{html:'<header><nav><a href="#features">Features</a></nav></header><main><h1>Our idea</h1><a href="#features">Explore</a><section id="features"><h2>Features</h2></section></main><footer>Made with care</footer>',css:'body { font-family: system-ui; margin: 0; }',js:''},solution:{html:'<header><nav><a href="#features">Features</a></nav></header><main><h1>Study together</h1><p>Make practice a habit.</p><a href="#features">See benefits</a><section id="features"><h2>Benefits</h2><div class="cards"><article><h3>Plan</h3><p>Choose a goal.</p></article><article><h3>Practice</h3><p>Build daily.</p></article></div></section><section><h2>Ready?</h2><a href="#features">Review benefits</a></section></main><footer>Study together</footer>',css:'body{font:1rem/1.5 system-ui;margin:0;color:#17202b}main,header,footer{padding:1rem;max-width:70rem;margin:auto}.cards{display:grid;gap:1rem}.cards article{padding:1rem;border:1px solid #bbc}a:focus-visible{outline:3px solid #174ea6}a{transition:color .2s}@media(min-width:40rem){.cards{grid-template-columns:repeat(2,1fr)}}@media(prefers-reduced-motion:reduce){a{transition:none}}',js:'',explanation:'The page begins as one column and expands when content has space. Links point to a real section, and keyboard focus stays visible.'}},
 {id:'project-3',title:'School Task Tracker',after:39,track:'js',minutes:240,brief:'Build a task tracker for school work. The exported tracker saves in its own browser and does not inherit WebSteps account syncing.',skills:['Forms','Arrays','DOM','Validation','Local storage'],requirements:['Add title, subject, optional due date','Edit tasks','Complete and uncomplete','Delete with confirmation or Undo','All, Active, Completed filters','Total and unfinished counts','Save and restore locally','Useful empty state','Reject whitespace-only titles','Stable IDs','Preserve input after validation error','Accessible labels and buttons','Completion indicated beyond color','Recover from damaged saved data'],extensions:['Search','Subject filter','Backup import/export'],starter:{html:'<h1>School tasks</h1><label>Task <input id="title"></label><button id="add">Add</button><p id="error"></p><ul id="tasks"></ul>',css:'body{font:1rem/1.5 system-ui}',js:'const tasks = []; // Build your tracker here'},solution:{html:'<h1>School tasks</h1><label>Task <input id="title"></label><button id="add">Add</button><p id="error"></p><ul id="tasks"></ul>',css:'body{font:1rem/1.5 system-ui}',js:'let tasks=[];try{const saved=JSON.parse(localStorage.getItem("tasks")||"[]");if(Array.isArray(saved))tasks=saved}catch{}const input=document.querySelector("#title"),list=document.querySelector("#tasks"),error=document.querySelector("#error");function render(){list.replaceChildren();for(const task of tasks){const li=document.createElement("li");li.textContent=task.title+" ";const done=document.createElement("button");done.textContent=task.done?"Mark active":"Complete";done.onclick=()=>{task.done=!task.done;save()};li.append(done);list.append(li)}}function save(){localStorage.setItem("tasks",JSON.stringify(tasks));render()}document.querySelector("#add").onclick=()=>{const title=input.value.trim();if(!title){error.textContent="Enter a task";return}error.textContent="";tasks.push({id:crypto.randomUUID(),title,done:false});input.value="";save()};render();',explanation:'This reference shows the core add and complete flow with stable IDs and damaged-data recovery. Continue with the remaining checklist requirements before self-review.'}},
 {id:'project-4',title:'Personal Portfolio',after:48,track:'integration',minutes:300,brief:'Combine the course into a responsive portfolio that introduces you and your projects, with a working theme and a data-driven section.',skills:['HTML','CSS','JavaScript','Accessibility','Publishing'],requirements:['Responsive introduction and about content','Project cards','Working navigation','Theme switching','Meaningful JavaScript interaction','Data-driven section','Accessible controls','Responsive and keyboard testing','Publishing instructions and verification checklist'],extensions:['Project filtering','Print stylesheet'],starter:{html:'<header><h1>My portfolio</h1><nav><a href="#projects">Projects</a></nav></header><main><section id="projects"><h2>Projects</h2></section></main>',css:'body{font:1rem/1.5 system-ui}',js:'// Add one meaningful interaction'},solution:{html:'<header><h1>My portfolio</h1><nav><a href="#projects">Projects</a></nav><button id="theme">Switch theme</button></header><main><section><h2>About</h2><p>I build useful websites.</p></section><section id="projects"><h2>Projects</h2><div id="cards"></div></section></main>',css:'body{font:1rem/1.5 system-ui;margin:2rem;color:#20242c}body.dark{background:#171a20;color:#fff}button:focus-visible,a:focus-visible{outline:3px solid royalblue}@media(max-width:40rem){body{margin:1rem}}',js:'const projects=[{title:"Introduction page"},{title:"Task tracker"}];const cards=document.querySelector("#cards");projects.forEach(project=>{const article=document.createElement("article");article.textContent=project.title;cards.append(article)});document.querySelector("#theme").onclick=()=>document.body.classList.toggle("dark");',explanation:'The cards come from data, navigation reaches a real section, and the button changes the theme. Verify it at narrow widths and with a keyboard before publishing.'}}
];
